/**
 * Part-layer frame data for the contour-cut character sprites.
 *
 * Each sprite layer is generated by tools/gen_sprites.py from a fixed canvas;
 * this table records, per layer:
 *   src        asset path
 *   w/h        source canvas size (aspect is used to place the layer)
 *   ax/ay      pivot as a fraction of the layer box (0..1), y measured from top
 *   ox/oy      where that pivot sits relative to the fighter origin
 *              (feet centre; oy negative = above the ground line)
 *   footOff    px between the canvas bottom edge and the drawn feet line
 *              (canvas-space, unscaled)
 *
 * The knight body/arm layers are saved on the FULL untrimmed canvas, so they
 * stack pixel-perfectly in CSS; the shoulder pivot lands at
 *   x = w*ax - w/2 (relative to the body box centre)
 *   y = -(h - footOff - h*ay) above the feet.
 * The knight sword arm and the nun launching arm are SEPARATE layers so they
 * can rotate/stretch independently of the body (see keyframes in
 * parts/frames.scss).
 */

export interface PartFrame {
  readonly src: string;
  readonly w: number;
  readonly h: number;
  readonly ax: number;
  readonly ay: number;
  readonly ox: number;
  readonly oy: number;
  /** Canvas-bottom -> feet-line gap in source pixels. */
  readonly footOff?: number;
}

export interface CharacterParts {
  /** Body-only layer (no animated weapon arm). */
  readonly idle: PartFrame;
  /** Flattened figure shown while attacking when no arm layer exists. */
  readonly attack: PartFrame;
  /** Separated animated arm (knight sword arm / nun cucumis arm). */
  readonly arm?: PartFrame;
  /** True when the body/arm PNGs are saved on the FULL untrimmed canvas. */
  readonly fullCanvas?: boolean;
}

/** CSS custom properties that size/position the layered rig box. */
export interface RigVars {
  readonly height: number; // px incl. foot gap
  readonly aspect: number; // width / height of the layer box
  readonly footOff: number; // px gap between canvas bottom and feet line
  readonly ax: string; // shoulder pivot x as % string of the layer box
  readonly ay: string; // shoulder pivot y as % string
}

const SPRITE_FIGURE_HEIGHT = 170; // px tall drawn figure on stage

/**
 * Computes the rig-box geometry for a character's idle frame: the box is
 * scaled so the DRAWN figure (canvas minus transparent bottom margin) is
 * exactly 170px tall with its feet on the ground line.
 */
export function rigVarsOf(parts: CharacterParts): RigVars {
  const f = parts.idle;
  const footOff = f.footOff ?? 0;
  const drawnH = f.h - footOff;
  const height = (SPRITE_FIGURE_HEIGHT * f.h) / drawnH;
  return {
    height,
    aspect: f.w / f.h,
    footOff: (height * footOff) / f.h,
    ax: `${((parts.arm?.ax ?? 0.5) * 100).toFixed(2)}%`,
    ay: `${((parts.arm?.ay ?? 0.5) * 100).toFixed(2)}%`,
  };
}

