export function partsFor(fighterId: string): CharacterParts | null {
  return CHARACTER_PARTS[fighterId] ?? null;
}

/** Attack phase of the separated arm layer, derived from move frame data. */
export type ArmPhase = 'windup' | 'launch' | 'recover';

/**
 * Maps engine frame data (startup / active / recovery windows) onto the arm
 * animation phase. Returns null when the fighter is not attacking — the arm
 * then runs its idle sway loop.
 */
export function armPhaseOf(
  stance: string,
  moveElapsedMs: number,
  startupMs: number,
  activeMs: number,
): ArmPhase | null {
  if (stance !== 'attack' && stance !== 'special' && stance !== 'mercy') {
    return null;
  }
  if (moveElapsedMs < startupMs) return 'windup';
  if (moveElapsedMs <= startupMs + activeMs) return 'launch';
  return 'recover';
}
